DO $pre$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.lf_operation_execution WHERE execution_id='EXEC-S30-LF-ASSURANCE-METHOD-V1-BASELINE-20260916-001' AND operation_code='ACTUALIZACION_ESTRATEGIA_LF' AND target_type='STRATEGY' AND target_code='LF_OPERATING_CONSTITUTION_POLICY_AUTONOMOUS_OPERATIONS_20260906' AND status='IN_PROGRESS') THEN RAISE EXCEPTION 'LF_ASSURANCE_S30_GOVERNED_EXECUTION_MISSING'; END IF;
  IF EXISTS (SELECT 1 FROM public.lf_assurance_evaluations) THEN RAISE EXCEPTION 'LF_ASSURANCE_PRODUCTIVE_EVALUATION_ALREADY_EXISTS'; END IF;
END $pre$;

-- Re-version existing obligations to give current material rows canonical provenance while preserving append-only history.
SELECT obligation_code,2,claim_code,claim_version,requirement_ref,implementation_ref,condition_ref,verification_method,positive_test_ref,negative_test_ref,adversarial_test_ref,structural_coverage_mode,evidence_contract,failure_taxonomy_code,required,'CANDIDATO',
'github://cristhianlujan/claude-persona-lf-patch/supabase/source_plans/s30_assurance_method_v1_workflow_router_completion.sql','EXEC-S30-LF-ASSURANCE-METHOD-V1-BASELINE-20260916-001'
FROM public.lf_assurance_obligation_catalog
WHERE version=1 AND obligation_code IN ('WF-DIAG-TEST-IDENTITY-V1','WF-DIAG-ASSERTION-V1','WF-DIAG-DURABLE-V1','ROUTER-EXEC-BIND-V1','ROUTER-OP-BIND-V1','ROUTER-TARGET-BIND-V1','ROUTER-FRESHNESS-V1','ROUTER-REPLAY-V1','ROUTER-ZERO-EFFECT-V1')
ON CONFLICT (obligation_code,version) DO NOTHING;

ON CONFLICT (obligation_code,version) DO NOTHING;

-- Current defeater provenance and explicit mechanisms for the newly materialized obligations.
SELECT defeater_code,2,claim_code,claim_version,
 CASE defeater_code WHEN 'ROUTER-D-SPOOF-V1' THEN 'ROUTER-SPOOF-RESISTANCE-V1' WHEN 'ROUTER-D-TOCTOU-V1' THEN 'ROUTER-TOCTOU-RESISTANCE-V1' ELSE obligation_code END,
 defeater_class,description,required_counterevidence,zero_effect_required,'CANDIDATO',
 'github://cristhianlujan/claude-persona-lf-patch/supabase/source_plans/s30_assurance_method_v1_workflow_router_completion.sql','EXEC-S30-LF-ASSURANCE-METHOD-V1-BASELINE-20260916-001'
FROM public.lf_assurance_defeater_catalog
WHERE version=1 AND defeater_code IN ('WF-D-STDOUT-LOSS-V1','ROUTER-D-WRONG-EXEC-V1','ROUTER-D-WRONG-TARGET-V1','ROUTER-D-STALE-V1','ROUTER-D-REPLAY-V1','ROUTER-D-SPOOF-V1','ROUTER-D-TOCTOU-V1')
ON CONFLICT (defeater_code,version) DO NOTHING;

ON CONFLICT (defeater_code,version) DO NOTHING;